 const identity={company_id:company,target_id:target};let available;
 for(let i=0;i<40;i++){r=await rpc('capability',identity);if(r.status===200){available=await r.json();break;}await r.arrayBuffer();await new Promise(resolve=>setTimeout(resolve,150));}
 assert.equal(available?.available,false,'actual RPC starts OFF');checks++;
 await db.query('update private.worker_document_admin_correction_state set enabled=true');
 r=await rpc('inspect',identity);assert.equal(r.status,200,'actual authorized inspection');const snapshot=(await r.json()).snapshot;
 assert.ok(Object.hasOwn(snapshot,'updated_by'));assert.ok(Object.hasOwn(snapshot,'template_version_id'));
 r=await rpc('correct',{...identity,request_id:request,expected_snapshot:snapshot,fields:{attachment_paths:[],expires_at:'2030-01-01',notes:'generated fixture correction'},reason:'generated fixture original-retention check'});
 assert.equal(r.status,200,'actual Data API full-row CAS');assert.equal((await r.json()).status,'applied');checks++;
 for(const object of paths){
  const history=(await db.query('select exists(select 1 from public.worker_document_status_history where $1=any(attachment_paths)) v',[object])).rows[0].v;assert.equal(history,true,'removed original in common history');
  const archived=(await db.query('select count(*)::int n from private.worker_document_admin_correction_photos where request_id=$1 and path=$2',[request,object])).rows[0].n;assert.equal(archived,1,'original object identity archived');
  r=await call('/storage/v1/object/authenticated/'+bucket+'/'+object,{token:session.access_token});assert.equal(r.status,200,'saved original remains readable');assert.deepEqual(Buffer.from(await r.arrayBuffer()),bytes);
  r=await call('/storage/v1/object/'+bucket+'/'+object,{token:session.access_token,method:'PUT',body:bytes,headers:{'Content-Type':'image/png'}});assert.ok([400,401,403,404].includes(r.status),'actual Storage overwrite denied');await r.arrayBuffer();checks++;
 }
 r=await call('/storage/v1/object/'+bucket,{token:session.access_token,method:'DELETE',json:{prefixes:paths}});
 if(r.status===200){assert.deepEqual(await r.json(),[],'retained originals cannot be returned as removed');}else{assert.ok([400,401,403,404].includes(r.status));await r.arrayBuffer();}checks++;
 for(const object of paths){r=await call('/storage/v1/object/authenticated/'+bucket+'/'+object,{token:session.access_token});assert.equal(r.status,200);assert.deepEqual(Buffer.from(await r.arrayBuffer()),bytes);}
 const afterIds=(await db.query('select id,name from storage.objects where bucket_id=$1 and name=any($2) order by name',[bucket,paths])).rows;
 assert.deepEqual(afterIds,objectIds.filter(x=>paths.includes(x.name)),'original object IDs/paths preserved');checks++;
 r=await call('/storage/v1/object/'+bucket,{token:session.access_token,method:'DELETE',json:{prefixes:[unused]}});assert.equal(r.status,200,'positive control unretained object removal');const removed=await r.json();assert.equal(removed.length,1);assert.equal((await db.query('select count(*)::int n from storage.objects where bucket_id=$1 and name=$2',[bucket,unused])).rows[0].n,0);checks++;
 await db.query('update private.worker_document_admin_correction_state set enabled=false');
 r=await rpc('get',{...identity,request_id:request});assert.equal(r.status,200);assert.equal((await r.json()).status,'applied');
 r=await rpc('correct',{...identity,request_id:randomUUID(),expected_snapshot:snapshot,fields:{attachment_paths:[],expires_at:null,notes:null},reason:'stopped fixture'});assert.ok([400,409,500].includes(r.status),'SQL55000 OFF response must not succeed');const stoppedError=await r.json();assert.equal(stoppedError.code,'55000');assert.equal(stoppedError.message,'administrator correction stopped');checks++;
 const createdSid=(await db.query('select session_id from private.worker_document_admin_corrections where request_id=$1',[request])).rows[0].session_id;assert.equal(createdSid,oldSid);
 const oldToken=session.access_token;r=await call('/auth/v1/logout?scope=local',{token:oldToken,method:'POST'});assert.ok([200,204].includes(r.status));await r.arrayBuffer();
 assert.equal((await db.query('select count(*)::int n from auth.sessions where id=$1',[oldSid])).rows[0].n,0);
