 session=await login(email,password);r=await rpc('get',{...identity,request_id:request});assert.equal(r.status,200);assert.equal((await r.json()).status,'applied');assert.equal((await db.query('select session_id from private.worker_document_admin_corrections where request_id=$1',[request])).rows[0].session_id,createdSid);checks++;
 const metadata=(await db.query("select p.oid::regprocedure::text signature,md5(pg_get_functiondef(p.oid)) definition_md5,md5(p.prosrc) source_md5 from pg_proc p where p.oid in(to_regprocedure('private.normalize_worker_document_photos()'),to_regprocedure('private.capture_worker_document_photo_baseline()'),to_regprocedure('public.capture_worker_document_status_history()'),to_regprocedure('private.worker_document_photos_are_retained(text)')) order by signature")).rows;
